ALTER TABLE member_user ADD experience BIGINT NOT NULL DEFAULT 0 COMMENT '当前累计经验余额';
ALTER TABLE member_user ADD level_id BIGINT NULL COMMENT '会员等级编号';
ALTER TABLE member_user ADD group_id BIGINT NULL COMMENT '会员分组编号';
ALTER TABLE member_user ADD sex INT NULL COMMENT '性别：0未知、1男、2女';
ALTER TABLE member_user ADD birthday DATE NULL COMMENT '出生日期';
CREATE TABLE member_session(id VARCHAR(36) PRIMARY KEY COMMENT '主键编号',member_id BIGINT NOT NULL COMMENT '会员编号',access_hash VARCHAR(64) NOT NULL UNIQUE COMMENT '访问令牌摘要',refresh_hash VARCHAR(64) NOT NULL UNIQUE COMMENT '刷新令牌摘要',expires_at DATETIME NOT NULL COMMENT '到期时间',refresh_expires_at DATETIME NOT NULL COMMENT '刷新令牌到期时间',FOREIGN KEY(member_id) REFERENCES member_user(id),KEY idx_member_session_owner(member_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT '会员访问与刷新会话';
CREATE TABLE member_address(id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '主键编号',user_id BIGINT NOT NULL COMMENT '会员编号',name VARCHAR(80) NOT NULL COMMENT '名称',mobile VARCHAR(24) NOT NULL COMMENT '手机号码',area_id BIGINT NOT NULL COMMENT '行政区划编号',detail_address VARCHAR(500) NOT NULL COMMENT '详细地址',default_status BOOLEAN NOT NULL DEFAULT FALSE COMMENT '是否默认收货地址',create_time DATETIME NULL COMMENT '创建时间',create_by VARCHAR(64) NULL COMMENT '创建人',update_time DATETIME NULL COMMENT '修改时间',update_by VARCHAR(64) NULL COMMENT '修改人',FOREIGN KEY(user_id) REFERENCES member_user(id),KEY idx_member_address_owner(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT '会员收货地址';
CREATE TABLE member_level(id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '主键编号',name VARCHAR(80) NOT NULL UNIQUE COMMENT '名称',level INT NOT NULL UNIQUE COMMENT '会员等级序号',experience BIGINT NOT NULL UNIQUE COMMENT '升级所需经验门槛',discount_percent INT NOT NULL COMMENT '等级折扣百分比，100表示不打折',icon VARCHAR(500) COMMENT '图标地址',background_url VARCHAR(500) COMMENT '等级背景图片地址',status INT NOT NULL COMMENT '等级状态：1启用、0停用',create_time DATETIME NULL COMMENT '创建时间',create_by VARCHAR(64) NULL COMMENT '创建人',update_time DATETIME NULL COMMENT '修改时间',update_by VARCHAR(64) NULL COMMENT '修改人') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT '会员等级';
CREATE TABLE member_group(id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '主键编号',name VARCHAR(80) NOT NULL UNIQUE COMMENT '名称',remark VARCHAR(500) COMMENT '备注说明',status INT NOT NULL COMMENT '分组状态：1启用、0停用',create_time DATETIME NULL COMMENT '创建时间',create_by VARCHAR(64) NULL COMMENT '创建人',update_time DATETIME NULL COMMENT '修改时间',update_by VARCHAR(64) NULL COMMENT '修改人') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT '会员分组';
CREATE TABLE member_tag(id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '主键编号',name VARCHAR(80) NOT NULL UNIQUE COMMENT '名称',remark VARCHAR(500) COMMENT '备注说明',create_time DATETIME NULL COMMENT '创建时间',create_by VARCHAR(64) NULL COMMENT '创建人',update_time DATETIME NULL COMMENT '修改时间',update_by VARCHAR(64) NULL COMMENT '修改人') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT '会员标签';
CREATE TABLE member_tag_link(member_id BIGINT NOT NULL COMMENT '会员编号',tag_id BIGINT NOT NULL COMMENT '会员标签编号',PRIMARY KEY(member_id,tag_id),FOREIGN KEY(member_id) REFERENCES member_user(id),FOREIGN KEY(tag_id) REFERENCES member_tag(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT '会员标签关联';
CREATE TABLE member_level_record(id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '主键编号',user_id BIGINT NOT NULL COMMENT '会员编号',level_id BIGINT NULL COMMENT '会员等级编号',user_experience BIGINT NOT NULL COMMENT '变更后会员经验余额',experience BIGINT NULL COMMENT '源记录经验：自动变更取等级门槛，手工调整取经验差值；历史未知为空',level INT NULL COMMENT '变更时等级序号快照',discount_percent INT NULL COMMENT '变更时等级折扣百分比快照',remark VARCHAR(500) NOT NULL COMMENT '备注说明',description VARCHAR(500) NULL COMMENT '描述说明',create_time DATETIME NOT NULL COMMENT '创建时间',create_by VARCHAR(64) NULL COMMENT '创建人',update_by VARCHAR(64) NULL COMMENT '修改人',update_time DATETIME NULL COMMENT '修改时间',FOREIGN KEY(user_id) REFERENCES member_user(id),KEY idx_member_level_record(user_id,id)) COMMENT '会员等级变更记录';
CREATE TABLE member_sign_in_config(id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '主键编号',`day` INT NOT NULL COMMENT '连续签到第几天',point BIGINT NOT NULL COMMENT '本档签到奖励积分',experience BIGINT NOT NULL COMMENT '本档签到奖励经验',status INT NOT NULL COMMENT '规则状态：1启用、0停用',create_time DATETIME NULL COMMENT '创建时间',create_by VARCHAR(64) NULL COMMENT '创建人',update_time DATETIME NULL COMMENT '修改时间',update_by VARCHAR(64) NULL COMMENT '修改人',UNIQUE KEY uk_member_sign_config_day(`day`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT '会员连续签到奖励规则';
CREATE TABLE member_sign_in_record(id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '主键编号',user_id BIGINT NOT NULL COMMENT '会员编号',sign_date DATE NOT NULL COMMENT '签到业务日期',`day` INT NOT NULL COMMENT '连续签到第几天',point BIGINT NOT NULL COMMENT '本次签到实际奖励积分',experience BIGINT NOT NULL COMMENT '本次签到实际奖励经验',create_time DATETIME NULL COMMENT '创建时间',create_by VARCHAR(64) NULL COMMENT '创建人',update_by VARCHAR(64) NULL COMMENT '修改人',update_time DATETIME NULL COMMENT '修改时间',UNIQUE KEY uk_member_sign_date(user_id,sign_date),FOREIGN KEY(user_id) REFERENCES member_user(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT '会员每日签到记录';
CREATE TABLE member_login_attempt(login_hash VARCHAR(64) PRIMARY KEY COMMENT '登录账号摘要',failures INT NOT NULL DEFAULT 0 COMMENT '登录失败次数',window_start DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '登录失败计数窗口开始时间') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT '会员登录失败计数';
ALTER TABLE member_user ADD CONSTRAINT fk_member_level FOREIGN KEY(level_id) REFERENCES member_level(id);
ALTER TABLE member_user ADD CONSTRAINT fk_member_group FOREIGN KEY(group_id) REFERENCES member_group(id);
